async function health(c){const r=await core(c,"/health","GET",{accept:"application/json","user-agent":"MUSITU-Axiom-Plugin-Gate/4.0"});let coreHealth={};try{coreHealth=await r.json()}catch{}let db=false;try{await c.db.prepare("SELECT 1 FROM oauth_access_tokens LIMIT 1").first();db=true}catch{}return{ok:r.status===200&&coreHealth.ok===true&&db,service:"MUSITU Axiom Public Plugin Gate",server_version:VERSION,oauth_enforced:true,submission_safe_commerce_profile:true,auth_issuer:c.issuer,resource:c.resource,oauth_db_ready:db,core:coreHealth,wolfram_parity:"NOT_CERTIFIED",superiority:"NOT_CERTIFIED"}}
function privacy(){return html(200,"MUSITU Axiom Privacy Policy",`<p>This policy describes data handled when you use the MUSITU Axiom plugin and its account-linking service.</p><h2>Data we process</h2><ul><li><strong>Account and entitlement data:</strong> the MUSITU customer record associated with the account you choose to connect.</li><li><strong>OAuth security data:</strong> client identifiers, requested scopes, hashed access and refresh tokens, authorization-code/flow records, expiry and revocation state. Raw OAuth tokens are not stored in these OAuth ledger tables.</li><li><strong>Usage data:</strong> the Axiom operation used, compute-unit usage, outcome/status, response timing, cryptographic request/result hashes, and an internal request identifier used for metering and abuse prevention.</li><li><strong>Content:</strong> only the operation arguments intentionally sent for the requested calculation. The plugin does not request the full ChatGPT conversation history.</li></ul><h2>Why we use it</h2><p>We use this data to authenticate your existing MUSITU account, deliver requested calculations, enforce entitlements and quotas, meter usage, prevent abuse, troubleshoot failures, and maintain security and audit integrity.</p><h2>Who receives it</h2><p>Data is processed by MUSITU and infrastructure providers used to operate the service, including Cloudflare and the private compute hosting layer. We do not sell plugin user data to advertisers. The public plugin does not collect card data and does not initiate digital-subscription checkout.</p><h2>Retention</h2><ul><li>Authorization flows expire after 10 minutes and authorization codes after 5 minutes.</li><li>OAuth access tokens expire after 1 hour; refresh tokens expire after 30 days. Hashed security ledger records may be retained with the account until deletion or longer when reasonably necessary for security investigations.</li><li>Account, entitlement, and metering records are retained while the MUSITU account remains active and until deletion is requested, except records that must be retained longer for security, fraud prevention, accounting, dispute resolution, or legal obligations.</li></ul><h2>Your controls</h2><p>You can revoke an OAuth session without changing the original MUSITU account credential. You may request access, correction, or deletion of account-linked personal data through the support contact published with this plugin, subject to legal retention requirements.</p>`)}
function terms(){return html(200,"MUSITU Axiom Terms of Use",`<p>MUSITU Axiom provides quantitative calculation and analytical tools. Results are informational and are not a guarantee of investment performance, financial advice, or an instruction to trade.</p><h2>Existing account access</h2><p>The public plugin uses OAuth to connect an existing MUSITU Axiom account and may use that account's existing entitlement when you invoke a metered capability. The plugin does not execute trades, transfer money, or complete subscription purchases.</p><h2>Acceptable use</h2><p>Do not use the service for unlawful activity, fraud, market manipulation, credential sharing, or attempts to bypass quotas, authentication, or security controls.</p><h2>Availability</h2><p>Outputs may contain errors and service availability may vary. Independently verify material financial decisions.</p><h2>Contact</h2><p>Use the MUSITU Axiom support page published with this plugin for account, privacy, or service questions.</p>`)}
function support(){return html(200,"MUSITU Axiom Support",`<p>Support for the MUSITU Axiom public plugin covers account linking, OAuth connection issues, quantitative tool availability, privacy requests, and service problems.</p><h2>Before requesting support</h2><ul><li>Confirm the MCP endpoint is <strong>https://mcp.mftintelligence.com/mcp</strong>.</li><li>Reconnect your existing MUSITU Axiom account if ChatGPT reports an authentication or scope error.</li><li>Do not send passwords, OAuth tokens, API keys, or other secrets in support requests.</li></ul><h2>Contact</h2><p><a href="https://support.mftintelligence.com/">MUSITU Axiom Official Support</a> · <a href="mailto:support@mftintelligence.com">support@mftintelligence.com</a></p><h2>Policies</h2><p><a href="/privacy">Privacy Policy</a> · <a href="/terms">Terms of Use</a> · <a href="/docs">Documentation</a></p>`)}
export default{async fetch(req,env){const c=cfg(env),u=new URL(req.url);if(!c.db||!c.core)return response(503,{error:"plugin_gate_not_configured"});if(req.method==="OPTIONS")return new Response(null,{status:204,headers:{"access-control-allow-origin":"*","access-control-allow-methods":"GET,POST,OPTIONS","access-control-allow-headers":"authorization,content-type,mcp-session-id,x-musitu-request-id"}});if(u.pathname==="/health"&&req.method==="GET"){const h=await health(c);return response(h.ok?200:503,h)}if(u.pathname==="/.well-known/oauth-protected-resource"&&req.method==="GET")return response(200,{resource:c.resource,authorization_servers:[c.issuer],scopes_supported:["axiom.execute"],resource_documentation:c.resource+"/docs"});if(u.pathname==="/.well-known/openai-apps-challenge"&&req.method==="GET")return c.challenge?new Response(c.challenge,{status:200,headers:{"content-type":"text/plain; charset=utf-8","cache-control":"no-store"}}):response(404,{error:"challenge_not_configured"});if(u.pathname==="/privacy"&&req.method==="GET")return privacy();if(u.pathname==="/terms"&&req.method==="GET")return terms();if(u.pathname==="/support"&&req.method==="GET")return support();if(u.pathname==="/docs"&&req.method==="GET")return html(200,"MUSITU Axiom Documentation",`<p>MUSITU Axiom provides quantitative finance, statistics, optimization, time-series, verification, and mathematical tools for users with an existing MUSITU Axiom account entitlement.</p><h2>Connect from ChatGPT</h2><p>Use the production MCP endpoint at <strong>${esc(c.resource+"/mcp")}</strong>. Authentication uses OAuth 2.1 with PKCE. Tool execution requires the <strong>axiom.execute</strong> scope; identity-only scopes do not grant compute access.</p><h2>Capabilities and boundaries</h2><ul><li>Use the public search and fetch tools to discover supported quantitative capabilities.</li><li>Authenticated capability calls use the existing MUSITU Axiom entitlement and metering boundary.</li><li>This public plugin does not expose subscription checkout tools, execute investment trades, or transfer money.</li></ul><h2>Policies and support</h2><p><a href="${esc(c.resource+"/privacy")}">Privacy Policy</a> · <a href="${esc(c.resource+"/terms")}">Terms of Use</a> · <a href="${esc("https://support.mftintelligence.com/")}">Support</a></p>`);if(u.pathname==="/mcp")return mcp(req,c);return response(404,{error:"not_found"})}};